def base(s):
    return 9.5 if s>=600 else 8.5 if s>=580 else 7.5 if s>=550 else 6.3 if s>=520 else 5.5 if s>=500 else 4.5 if s>=480 else 3.7 if s>=460 else 3.0 if s>=430 else 2.2 if s>=410 else 1.5
