LANG={'ARG':['es'],'BOL':['es'],'CHL':['es'],'COL':['es'],'CRI':['es'],'CUB':['es'],'DOM':['es'],'ECU':['es'],'ESP':['es'],'GTM':['es'],'MEX':['es'],'NIC':['es'],'PAN':['es'],'PER':['es'],'ABW':['es'],'BRA':['pt'],'PRT':['pt'],'ITA':['it'],'JPN':['ja'],'FRA':['fr'],'MAR':['ar','fr'],'EGY':['ar'],'JOR':['ar'],'ARE':['ar'],'MDG':['fr'],'PYF':['fr'],'RWA':['fr'],'SYC':['fr'],'MUS':['fr'],'DEU':['de'],'AUT':['de'],'CHE':['de','fr','it'],'CHN':['zh'],'TWN':['zh'],'KOR':['ko'],'KGZ':['ru'],'UZB':['ru'],'IND':['hi'],'NPL':['hi'],'MNG':['other'],'KHM':['other'],'THA':['other'],'VNM':['other'],'LAO':['other'],'MMR':['other'],'IDN':['other'],'LKA':['other'],'BTN':['other'],'GRC':['other'],'TUR':['other'],'GEO':['other'],'HRV':['other'],'HUN':['other'],'CZE':['other'],'DNK':['other'],'NOR':['other'],'FIN':['other'],'NLD':['other'],'ISL':['other'],'ETH':['other'],'TZA':['other'],'KEN':['other'],'UGA':['other'],'PAK':['other'],'MDV':['other'],'PHL':['other'],'MYS':['other'],'PNG':['other'],'NAM':['other'],'BWA':['other'],'ZMB':['other'],'ZWE':['other'],'GHA':[],'ZAF':['other'],'FLK':[],'ATA':[],'BHS':[],'BRB':[],'BLZ':['es'],'FJI':['other'],'PLW':['other'],'TCA':[],'JAM':[],'SGP':['zh'],'CAN':[],'USA':[],'GBR':[],'IRL':[],'AUS':[],'NZL':[]}
LANG_PLACE={'quebec-city':['fr'],'havana':['es'],'canaries':['es'],'puerto-rico':['es'],'los-cabos':['es'],'whistler':[],'azores':['pt'],'madeira':['pt'],'swissalps':['de','fr','it'],'dolomites':['it','de'],'hongkong':['zh'],'singapore':['zh'],'tokyo-kyoto':['ja'],'greenland':['other'],'faroe-islands':['other'],'belize':['es'],'texas-hill-country':['es'],'joshua-tree':['es'],'borabora':['fr'],'sardinia':['it'],'tbilisi-caucasus':['ru','other'],'nova-scotia':[],'kaziranga':['hi','other'],'kerala':['other'],'ladakh':['hi','other'],'rajasthan-golden-triangle':['hi'],'cape-town':['other'],'kruger':['other'],'egypt':['ar'],'bangkok':['other'],'peru':['es'],'peruvian-amazon':['es'],'mendoza':['es'],'uyuni':['es'],'atacama':['es'],'torres-del-paine':['es'],'tierra-del-fuego':['es'],'el-chalten':['es'],'argentine-lake-district':['es'],'colombian-caribbean':['es'],'colombian-andes':['es'],'ecuadorian-andes':['es'],'galapagos':['es'],'taiwan':['zh'],'seoul':['ko']}
if __name__=='__main__':
    d=json.load(open('/tmp/pilot_places.json')); out={}
    for x in d:
        i=x['id']; cc=x['cc']; t=x['type']
        nm=CC.get(cc); sc=EPI.get(nm) if nm else None
        f=min(10 if cc in ('NLD','DNK','NOR','SWE') else 9,round(base(sc)+ADJ[t])) if sc is not None else None
        if i in FORCE: e=FORCE[i]; how=f'EF EPI 2025 {sc}; set to {e} after research (transit signs and city menus work in English, conversation less so)'
        elif cc in NATIVE: e=NATIVE[cc]; how='English-speaking place'
        elif i in OVERRIDE and (f is None or abs(OVERRIDE[i]-f)>=2): e=OVERRIDE[i]; how=f'EF EPI 2025 {sc}; hand-adjusted from {f} for tourist reality' if f is not None else 'hand-judged (no EPI figure)'
        elif f is not None: e=f; how=f'EF EPI 2025 {sc}'
        else: e=OVERRIDE.get(i); how='hand-judged (no EPI figure)'
        if i in OVERRIDE and cc in NATIVE: e=OVERRIDE[i]; how='English-speaking place, adjusted'
        l=LANG_PLACE.get(i, LANG.get(cc))
        out[i]={'e':e,'how':how,'l':l,'f':f}
    json.dump(out,open('/tmp/english_out.json','w'))
    print([ (k,v) for k,v in out.items() if v['e'] is None or v['l'] is None])
    import collections; print(collections.Counter(v['e'] for v in out.values()))
